%[text] # A single circular wire loop  with current

syms  q  real 
syms t c epsilon0 mu0 theta real positive
syms x r z v_o real 
syms c_x c_y real 
syms vp_x vp_y real 


assumeAlso (r > 0)
assumeAlso (t > 0)
assumeAlso (z > 0)
assumeAlso (c > 0)
assumeAlso (v_o > 0)
assumeAlso (c_x > 0)
assumeAlso (c_y < 0)
assumeAlso (vp_x > 0)
assumeAlso (vp_y > 0)
assumeAlso (c - v_o > 0)
assumeAlso (c - vp_x > 0)
assumeAlso (c - vp_y > 0)
assumeAlso (c^2 - v_o^2 > 0)
assumeAlso (c^2 - vp_y^2 - vp_y^2 > 0)



% Define the position of the space where the force will be measured
r_p = [0, 0, 0];

% The velocity of the charged particle at r_p

vp = [vp_x,vp_y,0];



%%
%[text] ## Solving for the light vector reaching the charge at r\_p
% The circular loop will centered at x=[0,0,0] with a radius r in the x-y
% plane
% Light vector leaving the wire
cv = [c_x, c_y, 0];

%arbritary point in the wire

r_w = r*[-1,0,0];

% the velocity of the wire charges counter clockwise
v_w = v_o*[0,1,0];

% the light wire reaching the measurement point
eq_1 = r_w + (v_w+cv)*t - r_p == [0,0,0] %[output:38fa662c]
eq_2 = dot(cv,cv)-c^2==0 %[output:0ee7902f]

[ccx,ccy,tt,par,cond] = solve([eq_1(1),eq_1(2),eq_2],[c_x,c_y,t],"IgnoreAnalyticConstraints",true,ReturnConditions=true);

cc_x = simplify(expand(ccx(1)),'IgnoreAnalyticConstraints',true,'Criterion','preferReal','Steps',100), cc_y = simplify(ccy(1)),tt = simplify(tt(1),'IgnoreAnalyticConstraints',true,'Criterion','preferReal','Steps',100) %[output:7d779543] %[output:37fccad9] %[output:419f53d1]
%%
RotA = [cos(theta),-sin(theta),0;sin(theta),cos(theta),0;0,0,0]' %[output:400e06ad]
% Calculate data at point in loop
rt_w = [r,0,0]*RotA %[output:9f6cd1c0]
dRotA = diff(RotA,theta) %[output:932ea2a2]
vt_w = [v_o,0,0]*dRotA %[output:998d4dec]
cvec = -[cc_x,cc_y,0]*RotA %[output:0f88d33f]
plotrange=[0,2*pi];
posx=subs(rt_w,r,1) %[output:3bd21f77]
figure(1)
fplot(posx(1),plotrange) %[output:5df94842]
hold on %[output:5df94842]
posv=subs(vt_w,v_o,1) %[output:45574df0]
fplot(posv(1),plotrange) %[output:5df94842]
posc=subs(cvec,[c,v_o],[1,0.05]) %[output:0487541c]
fplot(posc(1),plotrange) %[output:5df94842]
hold off %[output:5df94842]
clf(1)
%%
%[text] ## The Point Force
%[text] 
k_e = q^2/(4*pi*epsilon0);

v_rel1 = cvec + vt_w;
v_rel2 = v_rel1 - vp;
ov = cvec/c;
v_rel1m = dot(v_rel1,v_rel1);
v_rel2m = dot(v_rel2,v_rel2);
p1 = (v_rel1m/v_rel2m)/c;
p2 = dot(ov,v_rel2);
R2 = r^2;
F_a = simplify(p1*p2/R2*ov) %[output:9ba676c0]
%%
%[text] ## Integrate the static charges
F_n = simplify(subs(F_a,v_o,0)) %[output:96ac03ab]
F_n = simplify(taylor(F_n,[vp_x,vp_y],[0,0],order=2),'IgnoreAnalyticConstraints',true,'Criterion','preferReal','Steps',100) %[output:8d61d0a4]
%%
syms L real positive

Ft_n = int(F_n,theta,0,2*pi) %[output:887bf36b]

%%
%[text] ## Integrating the current
% Define the velocity vector of the moving charge
F_ct = simplify(taylor(F_a,v_o,0,order=2),'IgnoreAnalyticConstraints',true,'Criterion','preferReal','Steps',100);
F_ct = simplify(taylor(F_ct,[vp_x,vp_y],[0,0],order=2),'IgnoreAnalyticConstraints',true,'Criterion','preferReal','Steps',100);
Ft_c = int(F_ct,theta,0,2*pi) %[output:3e68b09b]
%%

%%
%[text] ## The net force
F_atot = -k_e*simplify(Ft_c - Ft_n) %[output:5c1d0357]


